<?php
namespace App\Http\Controllers;
use App\Models\AuditLog; use App\Models\Event; use App\Models\Registration; use App\Models\StaffUser; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class StaffController extends Controller {
 public function loginForm(){return view('staff.login');}
 public function login(Request $request){$d=$request->validate(['username'=>['required'],'password'=>['required']]);$s=StaffUser::where('username',$d['username'])->where('is_active',true)->first();if(!$s||!Hash::check($d['password'],$s->password))return back()->withInput()->withErrors(['username'=>'Invalid username or password.']);$request->session()->regenerate();$request->session()->put('staff_user_id',$s->id);$request->session()->put('staff_name',$s->name);$request->session()->put('staff_role',$s->role);return redirect()->route('staff.dashboard');}
 public function logout(Request $request){$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('events.index');}
 public function dashboard(){$events=Event::withCount(['registrations as registered_count'=>fn($q)=>$q->whereIn('status',['confirmed','checked_in']),'registrations as checked_in_count'=>fn($q)=>$q->where('status','checked_in'),'registrations as waitlisted_count'=>fn($q)=>$q->where('status','waitlisted'),'registrations as cancelled_count'=>fn($q)=>$q->where('status','cancelled')])->orderBy('starts_at')->get();return view('staff.overview',compact('events'));}
 public function attendees(Request $request,Event $event){$search=$request->string('search')->trim();$registrations=$event->registrations()->when($search,fn($q)=>$q->where(fn($q)=>$q->where('full_name','like',"%{$search}%")->orWhere('ticket_code','like',"%{$search}%")))->latest('registered_at')->get();$registered=$event->registrations()->whereIn('status',['confirmed','checked_in'])->count();$checkedIn=$event->registrations()->where('status','checked_in')->count();return view('staff.list',compact('event','registrations','registered','checkedIn','search'));}
 public function checkinForm(Event $event){return view('staff.camera',compact('event'));}
 public function checkin(Request $request,Event $event){$d=$request->validate(['ticket_code'=>['required','string']]);$r=Registration::where('event_id',$event->id)->where('ticket_code',strtoupper(trim($d['ticket_code'])))->first();if(!$r)return back()->with('result',['type'=>'danger','title'=>'Invalid ticket','message'=>'This ticket does not belong to the selected event.']);if($r->status==='checked_in')return back()->with('result',['type'=>'warning','title'=>'Already checked in','message'=>$r->full_name.' was first checked in '.$r->checked_in_at->timezone('Asia/Manila')->format('M j, Y g:i A').'.']);if($r->status==='waitlisted')return back()->with('result',['type'=>'danger','title'=>'On waitlist — not confirmed','message'=>$r->full_name.' is not yet confirmed.']);if($r->status==='cancelled')return back()->with('result',['type'=>'danger','title'=>'Cancelled','message'=>'This ticket has been cancelled.']);if(!$event->starts_at->isToday())return back()->with('result',['type'=>'danger','title'=>'Check-in unavailable','message'=>'Tickets can only be checked in on the event day.']);$updated=Registration::whereKey($r->id)->where('status','confirmed')->update(['status'=>'checked_in','checked_in_at'=>now(),'checked_in_by'=>$request->session()->get('staff_user_id')]);if(!$updated)return back()->with('result',['type'=>'warning','title'=>'Already checked in','message'=>'This ticket was just checked in by another staff member.']);$this->audit($request,'checked_in',$r);return back()->with('result',['type'=>'success','title'=>'Checked in','message'=>$r->full_name.' has been checked in.']);}
 public function undoCheckin(Request $request,Event $event,Registration $registration){abort_unless($registration->event_id===$event->id,404);if($registration->status!=='checked_in')return back()->with('error','Only checked-in attendees can be undone.');$registration->update(['status'=>'confirmed','checked_in_at'=>null,'checked_in_by'=>null]);$this->audit($request,'checkin_undone',$registration);return back()->with('success','Check-in undone. This ticket can be checked in again.');}
 public function cancelRegistration(Request $request,Event $event,Registration $registration){abort_unless($registration->event_id===$event->id,404);if($registration->status==='checked_in')return back()->with('error','Checked-in registrations cannot be cancelled.');if($registration->status!=='cancelled'){$registration->update(['status'=>'cancelled','cancelled_at'=>now()]);$this->audit($request,'registration_cancelled',$registration);}return back()->with('success','Registration cancelled.');}
 public function promote(Request $request,Event $event){$confirmed=$event->registrations()->whereIn('status',['confirmed','checked_in'])->count();if($confirmed>=$event->capacity)return back()->with('error','There is no open spot to promote a waitlisted attendee.');$r=$event->registrations()->where('status','waitlisted')->orderBy('waitlist_position')->first();if(!$r)return back()->with('error','There is no one on the waitlist.');$r->update(['status'=>'confirmed','waitlist_position'=>null]);$this->audit($request,'waitlist_promoted',$r);return back()->with('success',$r->full_name.' has been promoted and can now check in.');}
 public function export(Event $event){$rows=$event->registrations()->orderBy('registered_at')->get();return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['Name','Email','Mobile','Ticket code','Status','Registered at','Checked in at']);foreach($rows as $r)fputcsv($out,[$r->full_name,$r->email,$r->mobile,$r->ticket_code,$r->status,$r->registered_at,$r->checked_in_at]);fclose($out);},'attendees-'.$event->id.'.csv',['Content-Type'=>'text/csv']);}
 public function createEvent(){return view('staff.event-form',['event'=>new Event]);}
 public function editEvent(Event $event){return view('staff.event-form',compact('event'));}
 public function storeEvent(Request $request){$event=Event::create($this->eventData($request));$this->audit($request,'event_created',$event);return redirect()->route('staff.dashboard')->with('success','Event created.');}
 public function updateEvent(Request $request,Event $event){$data=$this->eventData($request);$registered=$event->registrations()->whereIn('status',['confirmed','checked_in'])->count();if($data['capacity']<$registered)return back()->withInput()->withErrors(['capacity'=>"Capacity cannot be lower than the {$registered} active registrations."]);$event->update($data);$this->audit($request,'event_updated',$event);return redirect()->route('staff.dashboard')->with('success','Event updated.');}
 private function eventData(Request $request):array{$d=$request->validate(['title'=>['required','string','max:160'],'description'=>['required','string'],'venue'=>['required','string','max:160'],'starts_at'=>['required','date'],'ends_at'=>['required','date','after:starts_at'],'capacity'=>['required','integer','min:1'],'status'=>['required','in:draft,published,closed']]);return $d;}
 private function audit(Request $request,string $action,$target):void{AuditLog::create(['staff_user_id'=>$request->session()->get('staff_user_id'),'action'=>$action,'target_type'=>class_basename($target),'target_id'=>$target->id,'ip_address'=>$request->ip()]);}
}
